// The slice of ioredis's type surface the fixture code touches. The
// recognizer settles a call by where the method is declared, so the
// declarations have to be on disk under node_modules.

export default class Redis {
  constructor(url?: string);
  get(key: string): Promise<string | null>;
  setex(key: string, seconds: number, value: string): Promise<string>;
}
